#!/usr/bin/env python3
"""Verify provenance and assemble unchanged Rust slices. This is NOT a parser port."""
import argparse, hashlib, json, pathlib
BASE = pathlib.Path(__file__).resolve().parent
SOURCE = 'crates/codegen/xai-grok-update/src/community_release.rs'
RANGES = [(28,193),(232,276),(306,338),(344,474),(552,617),(633,1477)]
HEADER = '''// Generated by verify_sources.py. No parser implementation is handwritten here.
// Historical commit: 3f5d07f8cb2e9be395131296a3efc4635713db7f
use std::collections::{HashMap, HashSet};
use std::fs::{File, OpenOptions};
use std::io::{BufReader, Read, Write};
use std::path::Path;
use anyhow::{Context, Result};
use semver::Version;
use serde::Deserialize;
use sha2::{Digest, Sha256};
use futures::{Stream, StreamExt};
use indicatif::ProgressBar;
use tokio::io::AsyncWriteExt;
use crate::community_update_cancel;
#[path = "../historical/crates/codegen/xai-grok-product/src/lib.rs"]
mod xai_grok_product;
#[path = "../historical/crates/codegen/xai-grok-update/src/community_release/package_protocol.rs"]
mod package_protocol;
use package_protocol::{BUILD_INFO, PackageProtocol};
'''
def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--check',action='store_true'); args=ap.parse_args()
    provenance=json.loads((BASE/'source-provenance.json').read_text(encoding='utf-8'))
    report={'commit':provenance['commit'],'source_checks':[],'extraction_ranges':RANGES}
    for f in provenance['files']:
        b=(BASE/'historical'/f['path']).read_bytes()
        actual=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
        if actual != f['git_blob_sha1']: raise SystemExit(f"Git blob mismatch: {f['path']}")
        report['source_checks'].append({'path':f['path'],'git_blob_sha1':actual,'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'result':'PASS'})
    bridge=json.loads((BASE/'bridge-source-v1.0.8/provenance.json').read_text(encoding='utf-8'))
    b=(BASE/'bridge-source-v1.0.8/community_release.rs').read_bytes()
    bridge_blob=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
    assert bridge_blob==bridge['source']['git_blob_sha1'], 'v1.0.8 source blob changed'
    report['bridge_source_check']={'commit':bridge['tag']['object']['sha'],'git_blob_sha1':bridge_blob,'result':'PASS (source inspection only; not compiled)'}
    tag=json.loads((BASE/'historical-release-v1.0.45-tag.json').read_text(encoding='utf-8'))
    assert tag['tag']=='release-v1.0.45' and tag['object']['sha']==provenance['commit']
    lines=(BASE/'historical'/SOURCE).read_bytes().splitlines(keepends=True)
    generated=HEADER.encode()
    for start,end in RANGES:
        generated+=f'\n// Verbatim {SOURCE}:L{start}-L{end}\n'.encode()+b''.join(lines[start-1:end])
    generated+=b'\n#[cfg(test)]\n#[path = "compatibility_tests.rs"]\nmod compatibility_tests;\n#[cfg(all(windows, test))]\n#[path = "historical_transaction.rs"]\nmod transaction;\n'
    target=BASE/'src/historical.rs'
    if args.check:
        if target.read_bytes()!=generated: raise SystemExit('Generated Rust module differs from the verified historical slices')
    else: target.write_bytes(generated)
    auto_path='crates/codegen/xai-grok-update/src/auto_update.rs'
    auto=(BASE/'historical'/auto_path).read_bytes().splitlines(keepends=True)
    tty_path='crates/codegen/xai-tty-utils/src/lib.rs'
    tty=(BASE/'historical'/tty_path).read_bytes().splitlines(keepends=True)
    def exact(lines,path,start,end):
        return f'\n// Verbatim {path}:L{start}-L{end}\n'.encode()+b''.join(lines[start-1:end])
    tx=b'// Generated unchanged historical function bodies plus explicitly marked test seams.\nuse super::*;\n'
    for start,end in [(1716,1732),(2156,2273),(2880,3001),(3766,3783)]:
        tx+=exact(auto,auto_path,start,end)
    tx+=b'\n// Preserve the historical tools re-export destination without the application dependency graph.\nmod xai_grok_tools { pub mod util {\n'
    tx+=exact(tty,tty_path,171,190)+b'\n} }\n'
    tx+=b'\n// TEST SEAMS ONLY: fixture stream replaces HTTPS adapter; destination is an isolated genuine old EXE.\n'
    tx+=b'async fn isolated_transaction(asset: VerifiedAsset, destination: std::path::PathBuf, source: &Path, truncate_stream: bool) -> Result<String> {\n    let version = asset.version.clone();\n'
    tx+=exact(auto,auto_path,1161,1171)
    tx+=exact(auto,auto_path,1173,1174)
    tx+=b'\n    // Replaces only original L1175 download_verified network adapter call.\n    write_verified_download(&asset, &archive, &ProgressBar::hidden(), file_stream(source, truncate_stream)?).await?;\n'
    tx+=exact(auto,auto_path,1177,1231)
    tx+=b'\n    // Production success-receipt and UI block L1232-L1239 is deliberately excluded.\n    Ok(version)\n}\n'
    tx+=b'\ninclude!("transaction_tests.rs");\n'
    tx_path=BASE/'src/historical_transaction.rs'
    if args.check:
        if tx_path.read_bytes()!=tx: raise SystemExit('Historical transaction source or seam differs from the verified assembly')
    else: tx_path.write_bytes(tx)
    report['transaction_module_sha256']=hashlib.sha256(tx).hexdigest()
    report['transaction_provenance']={'source':auto_path,'helper_ranges':[(1716,1732),(2156,2273),(2880,3001),(3766,3783)],'install_windows_transaction_ranges':[(1161,1171),(1173,1174),(1177,1231)],'detach_source':tty_path,'detach_range':[171,190],'whole_install_community_release':'NOT CALLED; current_exe and production receipt deliberately outside isolated transaction seam','transport':'Local real archive stream passed to unchanged write_verified_download; live HTTP adapter excluded'}
    report['generated_module_sha256']=hashlib.sha256(generated).hexdigest()
    report['rust_execution']='NOT EXECUTED by this provenance checker'
    (BASE/'results').mkdir(exist_ok=True)
    (BASE/'results/source-provenance-check.json').write_text(json.dumps(report,indent=2)+'\n')
    print(f"PASS: {len(report['source_checks'])} exact Git blobs and {len(RANGES)} unchanged Rust ranges verified")
if __name__=='__main__': main()
